  rz?: number
  material: THREE.Material
}) {
  const geo = useMemo(
    () => new THREE.SphereGeometry(1, 22, 16, 0, Math.PI * 2, 0, Math.PI / 2),
    []
  )
  return (
    <mesh
      geometry={geo}
      position={position}
      scale={[rx, ry, rz]}
      rotation={[-Math.PI / 2, 0, 0]}
      material={material}
      castShadow
      receiveShadow
    />
  )
}

